const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const won=s=>s.c===2&&s.r===2;
export function initialState(){return {c:0,r:0,moves:0,msg:'Move the token to the green goal square.',hint:false};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const a=event.action;const s={...state};
if(won(s))return s;
if(a==='hint'){s.hint=true;s.msg=s.c<2?'Hint: moving right brings you one step closer.':'Hint: moving up brings you one step closer.';return s;}
const d=D[a];if(!d)return s;
const c=s.c+d[0],r=s.r+d[1];
if(c<0||c>2||r<0||r>2){s.msg='That move would leave the board.';return s;}
s.c=c;s.r=r;s.moves++;s.hint=false;
s.msg=won(s)?'Goal reached in '+s.moves+' moves; the shortest route is 4.':'Moved '+a+'. Keep going.';
return s;}
export function evaluate({state}){
const s=state||initialState();
const x=(s.c-1)*1.1,z=(1-s.r)*1.1,w=won(s);
const q=s.c<2?[0,0,-0.7071068,0.7071068]:[-0.7071068,0,0,0.7071068];
const dist=(2-s.c)+(2-s.r);
return {nodes:{tok:{position:[x,w?0.43:0.35,z]},hintArrow:{position:[x,0.35,z],quaternion:q,visible:s.hint&&!w}},readouts:{dist,moves:s.moves},goal:{status:w?'won':'playing',message:s.msg}};}
